#!/usr/bin/env python3
"""L-SI box 109: RF (and reference rules) on the M1 hard families generated by Oink (tools/oink/build, scripts/setup_oink.sh) and
on PGSolver's recursiveladder (experiments/hard-families/pgsolver_port.py).
Usage: m1_109.py FAMILY N.. -- MODE.. [--secs S]    FAMILY in counter_core counter_dp counter_m counter_ortl counter_qpt counter_rob
counter_rr counter_symsi tc tc+ recursiveladder. One line per (family, N, mode): n, m, iterations, switches, capped, wrong (vertices
whose winner differs from harness Zielonka), badstrat (complaints of harness verify.check), seconds; TIMEOUT lines when S is hit."""
import sys, os, subprocess, time, signal
HERE = os.path.dirname(os.path.abspath(__file__)); ROOT = os.environ.get("ROOT109") or os.path.abspath(os.path.join(HERE, "..", "..", ".."))
av = sys.argv[1:]; sys.argv = [sys.argv[0]]
sys.path[:0] = [HERE] + [os.path.join(ROOT, p) for p in ("experiments/new/box190", "experiments/new/box21", "experiments/new", "experiments/si", "experiments/harness")]
import pg, n6, zielonka, verify
secs = int(av[av.index("--secs") + 1]) if "--secs" in av else 120
i = av.index("--"); fam = av[0]; Ns = [int(x) for x in av[1:i]]; modes = [x for x in av[i + 1:] if not x.startswith("--") and not x.isdigit()]
class TimeUp(Exception): pass
def _alarm(*_): raise TimeUp()
signal.signal(signal.SIGALRM, _alarm)
for N in Ns:
    if fam == "recursiveladder":
        txt = subprocess.run([sys.executable, os.path.join(ROOT, "experiments/hard-families/pgsolver_port.py"), fam, str(N)], capture_output=True, text=True, check=True).stdout
    else:
        txt = subprocess.run([os.path.join(ROOT, "tools/oink/build", fam), str(N)], capture_output=True, text=True, check=True).stdout
    g = pg.parse("".join(l + "\n" for l in txt.splitlines() if not l.lstrip().startswith("%"))); m = sum(len(set(s)) for s in g.succ)
    try:
        signal.alarm(secs); z = list(zielonka.solve(g)); signal.alarm(0)
    except TimeUp: z = None
    for mode in modes:
        t0 = time.time()
        try:
            signal.alarm(secs); r = n6.run(g, mode, cap=10 ** 6); signal.alarm(0)
        except TimeUp:
            print(f"M109 {fam} {N} mode {mode} n {g.n} m {m} TIMEOUT after {secs} s", flush=True); continue
        st = [r["strat"][v] if r["win"][v] == g.owner[v] else None for v in range(g.n)]
        wrong = "NA" if z is None else sum(1 for v in range(g.n) if r["win"][v] != z[v])
        print(f"M109 {fam} {N} mode {mode} n {g.n} m {m} iterations {r['its']} switches {r['sw']} capped {r['capped']} wrong {wrong} badstrat {len(verify.check(g, r['win'], st))} secs {time.time() - t0:.1f}", flush=True)
